// Loader: (re)creates the selected component in place
void Main::_ld50_load(void *ctx)
{
    auto *self = static_cast<Main *>(ctx);
    self->_o34.unload();
    switch (self->_ld50_which.value()) {
    case 0: {
        auto *obj = new (self->_ld50_buf.data) Main_Delegate6();
        obj->mq_setup(self);
        self->_o34.attach(obj, obj, [](void *p) { static_cast<Main_Delegate6 *>(p)->~Main_Delegate6(); });
        obj->componentComplete();
        break;
    }
    case 1: {
        auto *obj = new (self->_ld50_buf.data) Main_Delegate7();
        obj->mq_setup(self);
        self->_o34.attach(obj, obj, [](void *p) { static_cast<Main_Delegate7 *>(p)->~Main_Delegate7(); });
        obj->componentComplete();
        break;
    }
    default: break;
    }
}

